Add-Type -AssemblyName System.Drawing
$dir=(Get-Location).Path+'\public\assets\images\catalog'
$files=@(Get-ChildItem -LiteralPath $dir -File)
$items=@()
foreach($f in $files){try{$src=[System.Drawing.Bitmap]::new($f.FullName);$x=[int]($src.Width*.10);$y=[int]($src.Height*.04);$w=[int]($src.Width*.80);$h=[int]($src.Height*.72);$crop=$src.Clone([System.Drawing.Rectangle]::new($x,$y,$w,$h),[System.Drawing.Imaging.PixelFormat]::Format24bppRgb);$small=[System.Drawing.Bitmap]::new(12,12);$g=[System.Drawing.Graphics]::FromImage($small);$g.InterpolationMode=[System.Drawing.Drawing2D.InterpolationMode]::HighQualityBilinear;$g.DrawImage($crop,0,0,12,12);$g.Dispose();$crop.Dispose();$src.Dispose();$v=New-Object double[] 144;$mean=0;for($py=0;$py -lt 12;$py++){for($px=0;$px -lt 12;$px++){$c=$small.GetPixel($px,$py);$z=(.299*$c.R+.587*$c.G+.114*$c.B)/255;$v[$py*12+$px]=$z;$mean+=$z}}$mean/=144;$norm=0;for($i=0;$i-lt144;$i++){$v[$i]-=$mean;$norm+=$v[$i]*$v[$i]};$norm=[math]::Sqrt($norm)+.00001;for($i=0;$i-lt144;$i++){$v[$i]/=$norm};$small.Dispose();$items+=[pscustomobject]@{Name=$f.Name;V=$v}}catch{}}
$parent=@{};foreach($it in $items){$parent[$it.Name]=$it.Name};function root([string]$n){while($parent[$n]-ne$n){$parent[$n]=$parent[$parent[$n]];$n=$parent[$n]};$n};function join([string]$a,[string]$b){$ra=root $a;$rb=root $b;if($ra-ne$rb){$parent[$rb]=$ra}}
for($i=0;$i-lt$items.Count;$i++){for($j=$i+1;$j-lt$items.Count;$j++){$dot=0;for($k=0;$k-lt144;$k++){$dot+=$items[$i].V[$k]*$items[$j].V[$k]};if((1-$dot)-lt .018){join $items[$i].Name $items[$j].Name}}}
$map=@{};foreach($it in $items){$r=root $it.Name;$map[$it.Name]=$r};$mapPath=Join-Path (Get-Location) 'visual-body-map.json';$map|ConvertTo-Json -Compress|Set-Content -Encoding UTF8 $mapPath;$g=$map.GetEnumerator()|Group-Object Value;$dups=@($g|Where-Object Count -gt 1);$removed=($dups|ForEach-Object{$_.Count-1}|Measure-Object -Sum).Sum;Write-Output ('FILES '+$items.Count);Write-Output ('GROUPS '+$g.Count);Write-Output ('DUP_GROUPS '+$dups.Count);Write-Output ('REMOVED '+$removed);$dups|Sort-Object Count -Descending|Select-Object -First 20|ForEach-Object{Write-Output ('GROUP '+($_.Group|ForEach-Object Name -join ', '))};Write-Output ('MAP '+$mapPath)
